import { items, collections } from '@wix/data';
import { Type } from '@wix/auto_sdk_data_collections';
/**
 * Formats a Date object as YYYY-MM-DD string
 */
function formatDateAsYYYYMMDD(date) {
    const year = date.getUTCFullYear().toString().padStart(4, '0');
    const month = date.getUTCMonth().toString().padStart(2, '0');
    const day = date.getUTCDate().toString().padStart(2, '0');
    return `${year}-${month}-${day}`;
}
/**
 * Formats a Date object as ISO-8601 datetime object
 */
function formatDateAsISO8601(date) {
    return { $date: date.toISOString() };
}
/**
 * Formats a Date object as hh:mm:ss.SSS time string
 */
function formatTimeAsHHMMSSMMM(date) {
    const hours = date.getUTCHours().toString().padStart(2, '0');
    const minutes = date.getUTCMinutes().toString().padStart(2, '0');
    const seconds = date.getUTCSeconds().toString().padStart(2, '0');
    const milliseconds = date.getUTCMilliseconds().toString().padStart(3, '0');
    return `${hours}:${minutes}:${seconds}.${milliseconds}`;
}
/**
 * Transforms a value to date string format (YYYY-MM-DD)
 */
const transformDateField = (value) => {
    try {
        if (value == null) {
            return value;
        }
        let dateValue;
        if (value instanceof Date) {
            dateValue = value;
        }
        else {
            dateValue = new Date(value);
            if (isNaN(dateValue.getTime())) {
                return value;
            }
        }
        return formatDateAsYYYYMMDD(dateValue);
    }
    catch {
        return value;
    }
};
/**
 * Transforms a value to datetime object format { $date: "ISO-8601" }
 */
const transformDateTimeField = (value) => {
    try {
        if (value == null) {
            return value;
        }
        let dateValue;
        if (value instanceof Date) {
            dateValue = value;
        }
        else {
            dateValue = new Date(value);
            if (isNaN(dateValue.getTime())) {
                return value;
            }
        }
        return formatDateAsISO8601(dateValue);
    }
    catch {
        return value;
    }
};
/**
 * Transforms a value to time string format (hh:mm:ss.SSS)
 */
const transformTimeField = (value) => {
    try {
        if (value == null) {
            return value;
        }
        let dateTimeValue;
        if (value instanceof Date) {
            dateTimeValue = value;
        }
        else {
            dateTimeValue = new Date(value);
            if (isNaN(dateTimeValue.getTime())) {
                return value;
            }
        }
        return formatTimeAsHHMMSSMMM(dateTimeValue);
    }
    catch {
        return value;
    }
};
/**
 * Registry maps with proper typing
 */
const FIELD_TRANSFORMERS = {
    DATE: transformDateField,
    DATETIME: transformDateTimeField,
    TIME: transformTimeField,
};
/**
 * Transforms item data fields based on the collection schema.
 * Uses the schema to determine field types and apply appropriate transformers and validators.
 * If no schema is provided, returns data unchanged (graceful degradation).
 */
export function transformFields(itemData, collectionSchema) {
    // Graceful degradation: if no schema, return data as-is
    if (!collectionSchema || !collectionSchema.fields) {
        return itemData;
    }
    // Build a map of fieldKey -> fieldType for quick lookup
    const fieldTypeMap = new Map();
    for (const field of collectionSchema.fields) {
        if (field.key && field.type) {
            fieldTypeMap.set(field.key, field.type);
        }
    }
    const transformed = {};
    for (const [key, value] of Object.entries(itemData)) {
        // Null/undefined values pass through unchanged
        if (value == null) {
            transformed[key] = value;
            continue;
        }
        // Look up the field type from schema
        const fieldType = fieldTypeMap.get(key);
        // If we have a field type, try to apply transformer and validator
        if (fieldType) {
            const transformer = FIELD_TRANSFORMERS[fieldType];
            // Apply transformer if one exists and value is valid
            if (transformer) {
                transformed[key] = transformer(value);
                continue;
            }
        }
        // Handle arrays recursively
        if (Array.isArray(value)) {
            transformed[key] = value.map((item) => {
                // For nested objects, recursively transform
                if (item &&
                    typeof item === 'object' &&
                    !Array.isArray(item) &&
                    !('$date' in item)) {
                    return transformFields(item, collectionSchema);
                }
                return item;
            });
            continue;
        }
        // Handle nested objects recursively
        if (typeof value === 'object' && !('$date' in value)) {
            transformed[key] = transformFields(value, collectionSchema);
            continue;
        }
        // Default: pass through unchanged
        transformed[key] = value;
    }
    return transformed;
}
/**
 * Loads collection schema with error handling.
 * Returns null if schema cannot be loaded.
 */
export async function loadCollectionSchema(collectionId) {
    try {
        if (!collectionId) {
            throw new Error('No collection ID provided');
        }
        const schema = await collections.getDataCollection(collectionId);
        return schema;
    }
    catch (err) {
        console.warn(`Failed to load collection schema for "${collectionId}":`, err);
        return null;
    }
}
/**
 * Gets the referenced collection ID for a reference field.
 * Returns null if the field is not found or is not a reference field.
 */
export async function getReferencedCollectionId(options) {
    const { referenceFieldId, getSchema } = options;
    const schema = await getSchema();
    if (!schema || !schema.fields) {
        return null;
    }
    const field = schema.fields.find((f) => f.key === referenceFieldId);
    if (!field) {
        return null;
    }
    let referencedCollectionId;
    if (field.type === Type.REFERENCE && field.typeMetadata?.reference) {
        referencedCollectionId =
            field.typeMetadata.reference.referencedCollectionId;
    }
    else if (field.type === Type.MULTI_REFERENCE &&
        field.typeMetadata?.multiReference) {
        referencedCollectionId =
            field.typeMetadata.multiReference.referencedCollectionId;
    }
    return referencedCollectionId || null;
}
export async function fetchFieldOptions(options) {
    const { collectionId, fieldId, getSchema } = options;
    // Use getReferencedCollectionId to check if it's a reference field
    const referencedCollectionId = await getReferencedCollectionId({
        referenceFieldId: fieldId,
        getSchema,
    });
    if (referencedCollectionId) {
        try {
            const result = await items
                .query(referencedCollectionId)
                .limit(1000)
                .find();
            return result.items;
        }
        catch (err) {
            console.error(`Failed to load reference items for field "${fieldId}" (collection: ${referencedCollectionId}):`, err);
            return [];
        }
    }
    // Not a reference field, get distinct values
    try {
        const query = items.query(collectionId);
        const result = await query.distinct(fieldId);
        return result.items;
    }
    catch (err) {
        console.error(`Failed to load distinct values for field "${fieldId}" (collection: ${collectionId}):`, err);
        return [];
    }
}
/**
 * Creates a new item in a referenced collection.
 * Gets the referenced collection ID from the reference field, loads its schema,
 * transforms the item data, and inserts the item.
 */
export async function createReferencedCollectionItem(options) {
    const { referenceFieldId, itemData, getSchema } = options;
    // Get the referenced collection ID
    const referencedCollectionId = await getReferencedCollectionId({
        referenceFieldId,
        getSchema,
    });
    if (!referencedCollectionId) {
        throw new Error(`Reference field "${referenceFieldId}" not found or is not a reference field`);
    }
    // Load the schema for the referenced collection
    const referencedCollectionSchema = await loadCollectionSchema(referencedCollectionId);
    // Transform the item data using the referenced collection's schema
    const transformedItemData = transformFields(itemData, referencedCollectionSchema);
    // Insert the item into the referenced collection
    try {
        return await items.insert(referencedCollectionId, transformedItemData);
    }
    catch (err) {
        console.error(`Failed to create item in referenced collection "${referencedCollectionId}" for field "${referenceFieldId}":`, err);
        throw err;
    }
}
